   {['remind','schedule','draft-remind'].includes(modal)&&<><p className="muted">{modal==='schedule'?'When should this message be sent?':'When would you like to be reminded?'}</p>{[['Later today',3],['Tomorrow',24],['This weekend',72],['Next week',168]].map(([name,hours])=><button className="option-row" key={name} onClick={()=>{const until=new Date(Date.now()+Number(hours)*3600000).toISOString();if(modal==='schedule')void sendDraft(until);else if(modal==='draft-remind')notify('Draft follow-up reminders are not implemented yet');else{void mutate('snooze',{until});setModal('')}}}><Icon name="clock"/>{name}<span className="top-spacer"/><small>{new Date(Date.now()+Number(hours)*3600000).toLocaleDateString('en-US',{weekday:'short',hour:'numeric',minute:'2-digit'})}</small></button>)}<div className="date-picker"><label>Pick a date and time<input type="datetime-local" value={date} onChange={e=>setDate(e.target.value)}/></label><button className="primary" disabled={!date||Date.parse(date)<=Date.now()} onClick={()=>{if(modal==='schedule')void sendDraft(new Date(date).toISOString());else if(modal==='remind'){void mutate('snooze',{until:new Date(date).toISOString()});setModal('')}}}>Set time</button></div></>}
   {modal==='label'&&<>{data.labels.filter(l=>l.accountId===data.activeAccountId).map(l=><button className="option-row" key={l.id} onClick={()=>{void mutate('label',{labelId:l.id});setModal('')}}><Icon name="tag"/>{l.name}{current?.labels.includes(l.id)&&<Icon name="check"/>}</button>)}<button className="option-row" onClick={()=>setModal('create-label')}>Create new label</button></>}
   {modal==='create-label'&&<form onSubmit={async e=>{e.preventDefault();try{await api('/labels',{name:newLabel,accountId:data.activeAccountId});await load();setModal('');setNewLabel('')}catch(e){notify((e as Error).message)}}}><input className="form-input" autoFocus placeholder="Label name" aria-label="Label name" value={newLabel} onChange={e=>setNewLabel(e.target.value)}/><button className="primary" disabled={!newLabel.trim()}>Create label</button></form>}
   {modal==='move'&&folders.filter(f=>f[0]!=='drafts').map(([id,name,,icon])=><button className="option-row" key={id} onClick={()=>{if(['inbox','done','trash','spam'].includes(id))void mutate(({inbox:'unarchive',done:'archive',trash:'trash',spam:'spam'} as Record<string,string>)[id]);else notify('Use labels to organize this conversation');setModal('')}}><Icon name={icon}/>{name}</button>)}
   {modal==='accounts'&&<>{data.accounts.map(a=><button className="option-row" key={a.id} disabled={sending||switchingAccount} onClick={()=>void switchAccount(a.id)}><span className="avatar">{a.name[0]}</span><span>{a.name}<small className="block">{a.email}</small></span>{a.id===data.activeAccountId&&<Icon name="check"/>}</button>)}<a className="option-row" href="/api/auth/google/start" onClick={e=>{if(!(data.providerStatus.google as {configured?:boolean})?.configured){e.preventDefault();notify('Google OAuth credentials are required before connecting Gmail')}}}><Icon name="mail"/>Connect Gmail</a></>}
   {modal==='snippets'&&<>{preferences?.snippets?.map(s=><button className="snippet-option" key={s.id} onClick={()=>{if(draft&&!draftLocked){if(composerRef.current)composerRef.current.insertText(s.body);else setDraft({...draft,body:draft.body+s.body,html:plainTextToComposerHTML(draft.body+s.body)})}setModal('')}}><strong>{s.title}</strong><small>{s.body}</small></button>)}<button className="option-row" onClick={()=>{setModal('');setPanel('settings');setSettingsPage('Snippets')}}>Manage snippets</button></>}
   {modal==='shortcuts'&&<div className="shortcut-grid">{[['Compose','C'],['Open conversation','Enter'],['Reply','R'],['Forward','F'],['Mark Done','E'],['Remind Me','H'],['Star','S'],['Read / unread','U'],['Select conversation','X'],['Undo','Z'],['Search','/'],['Command','⌘ K'],['Next / previous','J / K'],['Go to Inbox','G I'],['Go to Sent','G T'],['Back','Esc'],['Send','⌘ Enter']].map(([name,key])=><div key={name}>{name}<Key>{key}</Key></div>)}</div>}
