function Empty({title,description}:{title:string;description:string}){return <div className="empty"><Icon name="check" size={42}/><h2>{title}</h2><p>{description}</p></div>}
function formatDate(date:string){const d=new Date(date);if(new Date().toDateString()===d.toDateString())return d.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});return d.toLocaleDateString('en-US',{month:'short',day:'numeric'}).toUpperCase()}
function Settings({page,setPage,preferences:p,update,data,notify}:{page:string;setPage:(s:string)=>void;preferences:Preferences;update:(p:Partial<Preferences>)=>void;data:Bootstrap;notify:(s:string)=>void}){
 const [signature,setSignature]=useState(p.signature),[snippetName,setSnippetName]=useState(''),[snippetBody,setSnippetBody]=useState('');
 const sections:Record<string,string[]>={'Superhuman AI':['Autocomplete','Autocorrect','Auto Archive','Auto Drafts','Auto Labels','Knowledge Base','Reminders'],'Inbox':['Split Inbox','Split Inbox Library'],'Superhuman Mail for Sales':['HubSpot','Pipedrive','Salesforce','Recent Opens'],'Learn Superhuman Mail':['Guides','Shortcuts','Quick Tips'],'My Account':['Add Accounts','Edit Profile','Theme'],'Calendar':['Calendar Accounts','Meeting Links','Timezones','Scheduling'],'Notifications':['Notifications'],'Triage':['Auto Advance','Hide Empty Split Inboxes'],'Writing':['Emoji','Signatures','Snippets','Convert Hyphen to Bulleted List'],'Workflow':['Auto Bcc','Blocked Senders','Downloads','Images','Out of Office','Read Statuses'],'Advanced':['Backtick as Escape','Send + Mark Done','Show Sender Full Names']};
 if(page==='Theme')return <><button className="back-link" onClick={()=>setPage('')}>‹ All settings</button>{['light','dark'].map(t=><button className={`theme-choice ${p.theme===t?'chosen':''}`} key={t} onClick={()=>update({theme:t})}><span className={`theme-preview ${t}`}/>{t==='light'?'Light':'Dark'}{p.theme===t&&<Icon name="check"/>}</button>)}</>;
 if(page==='Signatures')return <><button className="back-link" onClick={()=>setPage('')}>‹ All settings</button><label className="setting-label">Signature<textarea value={signature} onChange={e=>setSignature(e.target.value)} placeholder="Your email signature"/></label><button className="primary" onClick={()=>{update({signature});notify('Signature saved')}}>Save</button></>;
 if(page==='Snippets')return <><button className="back-link" onClick={()=>setPage('')}>‹ All settings</button>{p.snippets?.map(s=><div className="saved-snippet" key={s.id}><strong>{s.title}</strong><p>{s.body}</p><button onClick={()=>update({snippets:p.snippets.filter(x=>x.id!==s.id)})}>Remove</button></div>)}<form onSubmit={e=>{e.preventDefault();update({snippets:[...p.snippets,{id:crypto.randomUUID(),title:snippetName,body:snippetBody}]});setSnippetName('');setSnippetBody('')}}><input className="form-input" aria-label="Snippet title" placeholder="Snippet title" value={snippetName} onChange={e=>setSnippetName(e.target.value)}/><textarea className="form-input" aria-label="Snippet body" placeholder="Snippet text" value={snippetBody} onChange={e=>setSnippetBody(e.target.value)}/><button className="primary" disabled={!snippetName||!snippetBody}>Add snippet</button></form></>;
 if(page==='Add Accounts'||page==='Calendar Accounts')return <><button className="back-link" onClick={()=>setPage('')}>‹ All settings</button>{data.accounts.map(a=><div className="saved-account" key={a.id}><strong>{a.name}</strong><small>{a.email}</small><span>{a.provider==='demo'?'Demo':'Gmail'}</span></div>)}<a className="primary connect-button" href="/api/auth/google/start" onClick={e=>{if(!(data.providerStatus.google as {configured?:boolean})?.configured){e.preventDefault();notify('Google OAuth credentials are required before connecting Gmail')}}}>Connect Gmail</a><p className="muted">{(data.providerStatus.google as {configured?:boolean})?.configured?'Google OAuth is configured.':'Google OAuth credentials have not been configured.'}</p><p className="muted">Outlook integration is not implemented yet.</p></>;
 if(page==='Split Inbox')return <><button className="back-link" onClick={()=>setPage('')}>‹ All settings</button><p>Choose the inbox sections you want to see.</p>{['Important','Other','Calendar'].map(s=><label className="setting-toggle" key={s}>{s}<input type="checkbox" checked={p.splitInbox.includes(s)} onChange={e=>update({splitInbox:e.target.checked?[...p.splitInbox,s]:p.splitInbox.filter(x=>x!==s)})}/></label>)}</>;
 if(page)return <><button className="back-link" onClick={()=>setPage('')}>‹ All settings</button><p className="muted">This feature is recorded in the parity inventory and has not been implemented yet.</p></>;
 return <div className="settings-list">{Object.entries(sections).map(([section,items])=><section key={section}><h3>{section}</h3>{items.map(item=>{const toggle=['Auto Advance','Hide Empty Split Inboxes','Backtick as Escape','Show Sender Full Names'].includes(item);return toggle?<label key={item} className="setting-toggle">{item}<input type="checkbox" checked={Boolean(p[item])} onChange={e=>update({[item]:e.target.checked})}/></label>:<button key={item} onClick={()=>setPage(item)}>{item}</button>})}</section>)}</div>
}

function dateGroup(value:string){const date=new Date(value),now=new Date();const days=(Date.UTC(now.getFullYear(),now.getMonth(),now.getDate())-Date.UTC(date.getFullYear(),date.getMonth(),date.getDate()))/86400000;if(days<7)return 'Last 7 days';if(date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth())return 'Earlier this month';const previous=new Date(now.getFullYear(),now.getMonth()-1,1);if(date.getFullYear()===previous.getFullYear()&&date.getMonth()===previous.getMonth())return 'Last month';return date.toLocaleDateString('en-US',{month:'long',year:'numeric'})}
